package io.github.diodeme.ji.host;

import io.github.diodeme.ji.agent.AgentRun;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;

/** Unified Host prompt path with recoverable reservation and atomic canonical completion. */
public final class PromptApplicationService {
    private final SessionApplicationService sessions;
    private final HostStore store;
    private final Map<String, Object> sessionLocks = new ConcurrentHashMap<>();
    private final Map<String, AgentRun.Result> outcomes = new ConcurrentHashMap<>();
    private final Map<String, HostStore.Commit> completed = new ConcurrentHashMap<>();
    private final Map<String, CompletableFuture<HostStore.Commit>> completions = new ConcurrentHashMap<>();

    public PromptApplicationService(SessionApplicationService sessions, HostStore store) {
        if (sessions.sessionStore() != store) {
            throw new IllegalArgumentException("Host adapters require one combined HostStore/SessionStore");
        }
        this.sessions = sessions;
        this.store = store;
    }

    public Acceptance prompt(String sessionId, String commandId, String text) {
        return prompt(sessionId, commandId, text, null);
    }

    public Acceptance prompt(String sessionId, String commandId, String text, long expectedSnapshotRevision) {
        return prompt(sessionId, commandId, text, Long.valueOf(expectedSnapshotRevision));
    }

    private Acceptance prompt(String sessionId, String commandId, String text, Long expectedSnapshotRevision) {
        if (commandId == null || commandId.isBlank()) throw new IllegalArgumentException("commandId must not be blank");
        if (text == null || text.isBlank()) throw new IllegalArgumentException("prompt must not be blank");
        String payloadHash = sha256(text.getBytes(StandardCharsets.UTF_8));
        synchronized (sessionLocks.computeIfAbsent(sessionId, ignored -> new Object())) {
            Optional<HostStore.CommandRecord> prior = store.command(sessionId, commandId, payloadHash);
            if (prior.isPresent()) {
                HostStore.CommandRecord record = prior.orElseThrow();
                if (record.status() == HostStore.Status.COMPLETED) {
                    HostStore.Commit commit = record.commit().orElseThrow();
                    return new Acceptance(commit.resultRef(), Optional.empty(), commit);
                }
                if (record.status() == HostStore.Status.RESERVED) {
                    HostStore.Snapshot current = store.snapshot(sessionId);
                    return new Acceptance(record.resultRef(), Optional.empty(),
                            new HostStore.Commit(record.acceptedSeq(), current.baseEventSeq(),
                                    current.revision(), record.resultRef()));
                }
            }
            if (sessions.hasActiveRun(sessionId)) throw new IllegalStateException("session.active_run");
            String runId = prior.map(HostStore.CommandRecord::resultRef).orElseGet(() -> "run-" + UUID.randomUUID());
            HostStore.Snapshot before = store.snapshot(sessionId);
            long expectedRevision = expectedSnapshotRevision == null
                    ? sessions.snapshot(sessionId).revision() : expectedSnapshotRevision;
            HostStore.Reservation reservation = store.reserve(
                    sessionId, commandId, payloadHash, runId, expectedRevision);
            AgentRun run;
            try {
                run = sessions.prompt(sessionId, runId, text);
            } catch (RuntimeException failure) {
                store.release(sessionId, commandId, payloadHash, runId);
                throw failure;
            }
            CompletableFuture<HostStore.Commit> completion = new CompletableFuture<>();
            completions.put(runId, completion);
            run.completion().whenComplete((result, failure) -> {
                try {
                    Optional<HostStore.CommandRecord> record = store.command(sessionId, commandId, payloadHash);
                    HostStore.Commit committed = record.flatMap(HostStore.CommandRecord::commit).orElse(null);
                    if (committed == null) {
                        store.release(sessionId, commandId, payloadHash, runId);
                        completion.completeExceptionally(failure == null
                                ? new IllegalStateException("Host completion was not committed") : failure);
                    } else {
                        if (result != null) outcomes.put(runId, result);
                        completed.put(runId, committed);
                        completion.complete(committed);
                    }
                } catch (RuntimeException completionFailure) {
                    completion.completeExceptionally(completionFailure);
                }
            });
            return new Acceptance(runId, Optional.of(run),
                    new HostStore.Commit(reservation.acceptedSeq(), before.baseEventSeq(), before.revision(), runId));
        }
    }

    public Optional<AgentRun.Result> outcome(String runId) {
        return Optional.ofNullable(outcomes.get(runId));
    }

    public Optional<HostStore.Commit> completed(String runId) {
        CompletableFuture<HostStore.Commit> completion = completions.get(runId);
        if (completion != null) return Optional.of(completion.join());
        return Optional.ofNullable(completed.get(runId));
    }

    public HostStore store() {
        return store;
    }

    public record Acceptance(String runId, Optional<AgentRun> run, HostStore.Commit commit) {}

    static String sha256(byte[] payload) {
        try {
            return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(payload));
        } catch (java.security.NoSuchAlgorithmException exception) {
            throw new IllegalStateException(exception);
        }
    }
}

