package io.github.diodeme.ji.host;

import io.github.diodeme.ji.agent.AgentRun;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;

/** Unified Host prompt path with recoverable reservation and atomic canonical completion. */
public final class PromptApplicationService {
    private final SessionApplicationService sessions;
    private final HostStore store;
    private final Map<String, Object> sessionLocks = new ConcurrentHashMap<>();
    private final Map<String, AgentRun> activeRuns = new ConcurrentHashMap<>();
    private final Map<String, CompletableFuture<Void>> waiters = new ConcurrentHashMap<>();

    public PromptApplicationService(SessionApplicationService sessions, HostStore store) {
        if (sessions.sessionRepository() != store) {
            throw new IllegalArgumentException("Host adapters require one combined HostStore/SessionRepository");
        }
        this.sessions = sessions;
        this.store = store;
    }

    public Acceptance prompt(String sessionId, String commandId, String text) {
        return prompt(sessionId, commandId, text, null);
    }

    public Acceptance prompt(String sessionId, String commandId, String text, long expectedSnapshotRevision) {
        return prompt(sessionId, commandId, text, Long.valueOf(expectedSnapshotRevision));
    }

    private Acceptance prompt(String sessionId, String commandId, String text, Long expectedSnapshotRevision) {
        if (commandId == null || commandId.isBlank()) throw new IllegalArgumentException("commandId must not be blank");
        if (text == null || text.isBlank()) throw new IllegalArgumentException("prompt must not be blank");
        String payloadHash = sha256(text.getBytes(StandardCharsets.UTF_8));
        synchronized (sessionLocks.computeIfAbsent(sessionId, ignored -> new Object())) {
            String candidateRunId = "run-" + UUID.randomUUID();
            long expectedRevision = expectedSnapshotRevision == null
                    ? sessions.snapshot(sessionId).revision() : expectedSnapshotRevision;
            HostStore.PromptAcceptance accepted = store.acceptPrompt(
                    sessionId, commandId, payloadHash, candidateRunId, expectedRevision,
                    "local", List.of(text), List.of());
            HostStore.Snapshot current = store.snapshot(sessionId);
            HostStore.Commit ack = store.command(sessionId, commandId, payloadHash)
                    .flatMap(HostStore.CommandRecord::commit)
                    .orElseGet(() -> new HostStore.Commit(
                            accepted.acceptedSeq(), current.baseEventSeq(), current.revision(), accepted.resultRef()));
            if (!accepted.startRequired()) {
                if (accepted.status() == HostStore.Status.QUEUED) {
                    waiters.computeIfAbsent(accepted.resultRef(), ignored -> new CompletableFuture<>());
                }
                return new Acceptance(accepted.resultRef(),
                        Optional.ofNullable(activeRuns.get(accepted.resultRef())), ack);
            }
            AgentRun run = startReserved(
                    sessionId, commandId, payloadHash, accepted.resultRef(), text, Optional.empty());
            return new Acceptance(accepted.resultRef(), Optional.of(run), ack);
        }
    }

    public Optional<AgentRun.Result> outcome(String runId) {
        return store.completion(runId).map(value -> new AgentRun.Result(
                runId, io.github.diodeme.ji.agent.AgentEvent.Outcome.valueOf(value.outcome())));
    }

    public Optional<HostStore.Commit> completed(String runId) {
        CompletableFuture<Void> waiter = waiters.get(runId);
        if (waiter != null) waiter.join();
        return store.completion(runId).map(HostStore.Completion::commit);
    }

    public FollowUpQueue resumeQueue(String sessionId, long expectedQueueRevision) {
        synchronized (sessionLocks.computeIfAbsent(sessionId, ignored -> new Object())) {
            FollowUpQueue resumed = store.resumeQueue(sessionId, expectedQueueRevision);
            drainNext(sessionId);
            return resumed;
        }
    }

    public HostStore store() {
        return store;
    }

    public record Acceptance(String runId, Optional<AgentRun> run, HostStore.Commit commit) {}

    private AgentRun startReserved(
            String sessionId, String commandId, String payloadHash, String runId, String text,
            Optional<HostStore.ClaimedPrompt> claim) {
        CompletableFuture<Void> waiter = waiters.compute(runId, (ignored, prior) ->
                prior == null || prior.isCompletedExceptionally() ? new CompletableFuture<>() : prior);
        AgentRun run;
        try {
            run = sessions.prompt(sessionId, runId, text);
        } catch (RuntimeException failure) {
            if (claim.isPresent()) store.rollbackClaim(sessionId, claim.orElseThrow());
            else store.release(sessionId, commandId, payloadHash, runId);
            waiter.completeExceptionally(failure);
            waiters.remove(runId, waiter);
            throw failure;
        }
        activeRuns.put(runId, run);
        run.completion().whenComplete((result, failure) -> completeRun(
                sessionId, commandId, payloadHash, runId, claim, waiter, failure));
        return run;
    }

    private void completeRun(
            String sessionId, String commandId, String payloadHash, String runId,
            Optional<HostStore.ClaimedPrompt> claim, CompletableFuture<Void> waiter, Throwable failure) {
        synchronized (sessionLocks.computeIfAbsent(sessionId, ignored -> new Object())) {
            try {
                if (store.completion(runId).isEmpty()) {
                    if (claim.isPresent()) store.rollbackClaim(sessionId, claim.orElseThrow());
                    else store.release(sessionId, commandId, payloadHash, runId);
                    waiter.completeExceptionally(failure == null
                            ? new IllegalStateException("Host completion was not committed") : failure);
                    return;
                }
                waiter.complete(null);
                drainNext(sessionId);
            } catch (RuntimeException completionFailure) {
                waiter.completeExceptionally(completionFailure);
            } finally {
                activeRuns.remove(runId);
                if (!waiter.isCompletedExceptionally()) waiters.remove(runId, waiter);
            }
        }
    }

    private void drainNext(String sessionId) {
        Optional<HostStore.ClaimedPrompt> next = store.claimNextPrompt(sessionId);
        if (next.isEmpty()) return;
        HostStore.ClaimedPrompt claim = next.orElseThrow();
        String text = String.join("\n", claim.item().content());
        startReserved(sessionId, claim.item().commandId(), claim.payloadHash(), claim.resultRef(),
                text, Optional.of(claim));
    }

    static String sha256(byte[] payload) {
        try {
            return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(payload));
        } catch (java.security.NoSuchAlgorithmException exception) {
            throw new IllegalStateException(exception);
        }
    }
}
